# Let's construct K_{6,6} and verify it's maximal triangle-free
n = 12
A = list(range(6))
B = list(range(6, 12))
edges = set()
for u in A:
    for v in B:
        edges.add((u, v))

print(f"Number of edges: {len(edges)}")

# Check triangle-free
has_triangle = False
for u in range(n):
    for v in range(u+1, n):
        for w in range(v+1, n):
            if (u,v) in edges and (v,w) in edges and (u,w) in edges:
                has_triangle = True
                print(f"Triangle found: {u},{v},{w}")
print(f"Has triangle: {has_triangle}")

# Check maximal: for each missing edge, check if adding it creates a triangle
missing = []
for u in range(n):
    for v in range(u+1, n):
        if (u,v) not in edges:
            missing.append((u,v))

print(f"Number of missing edges: {len(missing)}")

creates_triangle = True
for u,v in missing:
    # Check if there exists w such that u-w and v-w are edges
    found = False
    for w in range(n):
        if w == u or w == v:
            continue
        # Need edges (u,w) and (v,w) in graph
        uw = (min(u,w), max(u,w))
        vw = (min(v,w), max(v,w))
        if uw in edges and vw in edges:
            found = True
            break
    if not found:
        print(f"Adding edge ({u},{v}) does NOT create a triangle")
        creates_triangle = False
        break

print(f"All missing edges create triangle: {creates_triangle}")
